REVOKE EXECUTE ON FUNCTION public.payment_audit(),public.track_sales_sequence(),public.quotation_archive_children() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.immutable_issued_brand() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF OLD.issued_at IS NOT NULL AND (NEW.brand_snapshot IS DISTINCT FROM OLD.brand_snapshot OR NEW.invoice_date IS DISTINCT FROM OLD.invoice_date OR NEW.order_date IS DISTINCT FROM OLD.order_date OR NEW.client_name IS DISTINCT FROM OLD.client_name OR NEW.client_id IS DISTINCT FROM OLD.client_id OR NEW.client_address IS DISTINCT FROM OLD.client_address OR NEW.due_date IS DISTINCT FROM OLD.due_date OR NEW.notes IS DISTINCT FROM OLD.notes OR NEW.section IS DISTINCT FROM OLD.section OR NEW.discount_type IS DISTINCT FROM OLD.discount_type OR NEW.discount_value IS DISTINCT FROM OLD.discount_value OR NEW.tax_enabled IS DISTINCT FROM OLD.tax_enabled OR NEW.tax_rate IS DISTINCT FROM OLD.tax_rate) THEN RAISE EXCEPTION 'Snapshot dan nilai invoice terbit terkunci'; END IF; RETURN NEW; END $$;
CREATE FUNCTION public.quotation_snapshot_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF OLD.status IN ('terkirim','disetujui') AND NEW.status<>'draft' AND (NEW.brand_snapshot IS DISTINCT FROM OLD.brand_snapshot OR NEW.client_name IS DISTINCT FROM OLD.client_name OR NEW.document_date IS DISTINCT FROM OLD.document_date OR NEW.client_address IS DISTINCT FROM OLD.client_address OR NEW.notes IS DISTINCT FROM OLD.notes OR NEW.discount_value IS DISTINCT FROM OLD.discount_value OR NEW.tax_rate IS DISTINCT FROM OLD.tax_rate) THEN RAISE EXCEPTION 'Snapshot penawaran final terkunci'; END IF; RETURN NEW; END $$;
CREATE TRIGGER quotation_snapshot_guard BEFORE UPDATE ON public.quotations FOR EACH ROW EXECUTE FUNCTION public.quotation_snapshot_guard();